# -*- coding: utf-8 -*-
"""
Generates IELTS Speaking L01-L10 (61+ pages each)
Structure per lesson:
  cover+agenda+review+objectives+pain_point = 5
  PART01-04 each: section+concept+concept+content+content+example+example = 7x4 = 28
  PART05 vocab: section+vocab+vocab+vocab+two_col = 5
  PART06 method: section+steps+steps+model+model+compare+compare = 7
  PART07 drill: section+drill*5 = 6
  PART08 pitfall: section+pain_point+content+content+tip_card+tip_card = 6
  checklist+summary+homework+preview = 4
  TOTAL = 61
"""
import sys, os
sys.path.insert(0, os.path.dirname(__file__))
import ppt_utils as U

OUT = os.path.join(os.path.dirname(__file__), "speaking")
os.makedirs(OUT, exist_ok=True)

def T():
    U.set_theme(U.RGBColor(0xA3,0x36,0x07), U.RGBColor(0xF2,0x8C,0x1D),
                U.RGBColor(0xFF,0xF3,0xE0), U.RGBColor(0x5C,0x1A,0x00),
                '口语','IELTS Speaking')

def part(p,idx,tc,te,concs,conts,exs):
    U.section(p,idx,tc,te)
    for c in concs: U.concept(p,c[0],c[1],c[2],note=c[3] if len(c)>3 else None)
    for c in conts: U.content(p,c[0],c[1],note=c[2] if len(c)>2 else None)
    for e in exs:   U.example(p,e[0],e[1],answer=e[2],tip=e[3])

# ══════════════════════════════════════════════════════════════════════════════
#  L01  口语考试全貌与评分框架
# ══════════════════════════════════════════════════════════════════════════════
def L01():
    T(); p=U.new_prs()
    U.cover(p,'口语',1,'口语考试全貌\n& 评分框架','Speaking Overview & Scoring Framework')
    U.agenda(p,['考试结构与三个Part','四维评分标准','深圳学生失分模式','备考策略框架',
                '核心术语','备考路线','课堂练习','小结作业'])
    U.content(p,'10节课口语学习路线图',
        [('L01','考试全貌+评分框架 → 知道考什么、怎么评分'),
         ('L02','Part 1 日常问答 → 建立基础答题模板'),
         ('L03-L04','Part 2 独白攻略（人物/地点/经历/物品）'),
         ('L05','Part 3 学术讨论 → 构建论点，深度分析'),
         ('L06-L09','词汇/流利度/语法/发音四维专项提升'),
         ('L10','全真模考+冲刺 → 查漏补缺，冲刺目标分')],
        note='每节课配合Part 1/2/3真题练习；建议每天开口说英语至少15分钟')
    U.objectives(p,['掌握雅思口语三个Part的结构、时长与评分重点',
                    '理解四个评分维度（CC/LR/GRA/P）各占25%的含义',
                    '识别自身最主要的失分类型，制定针对性提升计划',
                    '建立正确的口语备考心态：开口>完美'])
    U.pain_point(p,'深圳学生口语三大痛点',
        ['词穷：想法有，说不出——脑中有中文，嘴里找不到英文对应词，沉默超过3秒',
         '中式英语：说出来了但考官听起来"奇怪"——逐字翻译中文思路，语序/搭配/习惯表达全错',
         '紧张到说不出：Part 3难题一来就"脑子空白"——不是不会，是心理压力让语言能力下降'],
        ['词汇激活：每个话题建立20个"可以立刻说出口"的词，而非背单词表',
         '句式模板：建立10个万能句式框架，减少实时翻译的认知负担',
         '心理建设：口语不是"说完美的英语"，是"用不完美的英语完成沟通"——开口是关键'])
