    part(p,4,'填充语系统与流利度管理','Filler Systems & Fluency Management',
        [('填充语的正确使用','用自然填充语替代"um/uh"',
          [('功能','为自己争取思考时间，同时保持语流自然'),
           ('一级填充语（思考中）','Well... / Let me think... / That\'s an interesting question...'),
           ('二级填充语（组织观点中）','Actually... / To be honest... / I suppose...'),
           ('三级填充语（举例前）','For instance... / Like... / Such as...'),
           ('禁忌','避免连续用"um, um, um"——这是CC分杀手'),
           ('练习方法','把"um"替换成"well"——先从这一个改变开始')]),
         ('连接词：让答案有逻辑','Discourse Markers',
          [('添加信息','Besides that / On top of that / Not only that / What\'s more'),
           ('转折对比','That said / Even so / Having said that / On the other hand'),
           ('举例引入','For instance / Such as / Take [X] for example / A case in point is'),
           ('总结收尾','Overall / In general / All in all / When I think about it...'),
           ('深圳学生问题','多用and+and+and，少用转折和对比——GRA和CC都受影响')])],
        [('填充语练习方法',
          [('Step 1','把"um"替换成"Well,"——专注这一个改变，其他不变'),
           ('Step 2','在答案开头先停1秒（不出声），再说"Well..."——给大脑时间'),
           ('Step 3','准备3个Part 3时间争取句："That\'s an interesting point..."'),
           ('录音检查','录音回放时，数"um/uh"出现几次，目标：减少到3次以下/分钟'),
           ('自然度检查','填充语不要说得太正式——"Well">"Certainly, that is a question I find...（太刻意）"')]),
         ('连接词使用进阶',
          [('初级错误','I like it and it is good and I always do it on weekends and...'),
           ('进阶表达','I genuinely enjoy it, mainly because... What\'s more, it gives me...'),
           ('对比升级','I like outdoor activities. But I also like staying home.（弱）→That said, I do enjoy a quiet evening in as well.（强）'),
           ('举例升级','For example, I read.（弱）→For instance, I recently finished a fascinating book about...（强）'),
           ('总结升级','In a word, I like it.（弱）→All in all, it\'s become a really important part of my routine.（强）')])],
        [('填充语实战训练',
          '以下题目在回答前先停顿2秒，然后用一个自然的填充语开头：\n\n'
          '"What kind of music do you enjoy?"\n'
          '"Did you use to have any hobbies as a child that you\'ve given up?"\n'
          '"Do you think people in your country are becoming more health-conscious?"\n\n'
          '每个填充语只用一次（第1题用Well/第2题用Actually/第3题用To be honest）',
          '参考开头：\n①Well, I\'d say I have quite varied tastes actually...\n②Actually, now that you mention it, I used to be really into...\n③To be honest, I think there\'s definitely a growing awareness about health in Shenzhen...',
          '填充语后立刻接内容——不要"Well... um... I think... um... it\'s..."连续多个填充语'),
         ('答案完整性检查',
          '用以下5个问题检查你的答案是否完整：\n\n'
          '① 我直接回答了问题吗？（D）\n'
          '② 我给了至少一个原因吗？（R）\n'
          '③ 我举了一个具体例子吗？（E）\n'
          '④ 我用了话题词汇吗？（不是good/nice/like）\n'
          '⑤ 我说了至少30秒吗？',
          '5个全是Yes = 完整答案（目标）\n3-4个Yes = 良好但可提升\n少于3个Yes = 需要用DRE框架重新组织答案',
          '这5个问题在考场也适用：每答完一题，内心快速过一遍这5个检查点')]
    )
