        '"Describe a gift you received that was important to you."',
        'The gift that comes to mind is a wristwatch my father gave me when I started university. It\'s not an expensive brand, but it\'s beautifully simple — a silver-faced watch with a leather strap that I\'ve replaced three times now. My father gave it to me the morning I left for Shenzhen, and he said something I\'ve never forgotten: "Time is the only resource you can\'t earn back." I wear it every day, and every time I check the time, I\'m reminded of that moment. Over the years, it\'s survived job interviews, late-night study sessions, and my first board meeting. More than a timekeeping device, it\'s a kind of anchor — a physical reminder of the values he tried to instil in me.',
