         ('Part 2（更早的过去）','I had already.../I\'d always wanted to...（过去完成时）'),
         ('Part 2（现在反思）','Looking back, I realise... / This experience taught me...'),
         ('Part 3（观点）','I think... / This may/might/could lead to...'),
