         ('L03-L05（Part 2+3）','Part 2用1分钟关键词准备，Part 3用PEEL/PEELA框架，4大题型识别'),
         ('L06-L07（词汇+流利度）','话题词汇替换系统，5大话题词库，7种连接词，填充语代替um/uh'),
         ('L08-L09（语法+发音）','复合句3类，时态一致，th/v/w发音，句末降调，Shadowing训练'),
