         '"Part 2 开场：The [topic] that springs to mind is..."——在心里说一遍',
         '"Part 3 开场：I\'d argue that... / The way I see it..."——在心里说一遍',
         '"5个话题词汇：教育/科技/环境/社会/文化各想2个词"——确认词汇激活',
